// computeSessionLanes analyzes the flat list and assigns session lanes to checkpoints.
// Lanes are assigned based on session continuity, with the active session in lane 1.
func (m *Model) computeSessionLanes() {
	m.sessionLanes = make(map[int]SessionLaneInfo)

	// First pass: collect all checkpoints with their sessions
	type checkpointEntry struct {
		index     int
		sessionID string
		isActive  bool
	}
	var checkpoints []checkpointEntry

	for i, node := range m.flatList {
		if node.Type != NodeTypeCheckpoint {
			continue
		}
		sessionID := node.SessionID
		if sessionID == "" {
			continue
		}
		checkpoints = append(checkpoints, checkpointEntry{
			index:     i,
			sessionID: sessionID,
			isActive:  node.IsActive,
		})
	}

	if len(checkpoints) == 0 {
		return
	}

	// Find the active session (if any)
	var activeSessionID string
	for _, cp := range checkpoints {
		if cp.isActive {
			activeSessionID = cp.sessionID
			break
		}
	}

	// Track session to lane mapping and lane availability
	sessionToLane := make(map[string]int)
	laneInUse := [maxSessionLanes]bool{}

	// Track first and last occurrence of each session in the list
	sessionFirstIdx := make(map[string]int)
	sessionLastIdx := make(map[string]int)
	for _, cp := range checkpoints {
		if _, seen := sessionFirstIdx[cp.sessionID]; !seen {
			sessionFirstIdx[cp.sessionID] = cp.index
		}
		sessionLastIdx[cp.sessionID] = cp.index
	}

	// Process checkpoints in order (newest first in display)
	for i, cp := range checkpoints {
		lane := 0
		isStart := cp.index == sessionFirstIdx[cp.sessionID]
		isEnd := cp.index == sessionLastIdx[cp.sessionID]

		// Check if this session already has a lane
		if existingLane, hasLane := sessionToLane[cp.sessionID]; hasLane {
			lane = existingLane
		} else {
			// Assign a new lane - active session gets lane 1 priority
			if cp.sessionID == activeSessionID && !laneInUse[0] {
				lane = 1
				laneInUse[0] = true
				sessionToLane[cp.sessionID] = lane
			} else {
				// Find first available lane
				for l, inUse := range laneInUse {
					if !inUse {
						lane = l + 1
						laneInUse[l] = true
						sessionToLane[cp.sessionID] = lane
						break
					}
				}
			}
		}

		// Determine position in session
		var position LanePosition
		switch {
		case lane == 0:
			position = LanePositionNone
		case isStart && isEnd:
			position = LanePositionSingle
		case isStart:
			position = LanePositionStart
		case isEnd:
			position = LanePositionEnd
		default:
			position = LanePositionMiddle
		}

		// Build active mask - which lanes have lines at this row
		var activeMask [maxSessionLanes]bool
		for sid, l := range sessionToLane {
