			if state.IsActive {
				result.WriteString(laneActiveStyle.Render(char))
			} else {
				result.WriteString(laneInactiveStyle.Render(char))
			}
		} else {
			result.WriteString(char)
		}
		result.WriteString(" ") // Space between lanes
	}

